import { MigrateUpArgs, MigrateDownArgs, sql } from '@payloadcms/db-postgres'
import { enableRlsOnPayloadTables } from '../db/enable-rls'

// M3-13: toolkit files (DECISIONS §2.16 decision 9, §2.17; DATA-MODEL §4.5
// Toolkit), collection toolkit-files (localized label, prefix 'toolkits'),
// and the ordered, non-localized `files` list of a Learning Hub resource
// (lh_resources_rels, _lh_resources_v_rels).
// Additive only: two enums, four new tables, one nullable column on
// payload_locked_documents_rels. No existing column is altered or dropped.
// Generated by `payload migrate:create`; added by hand:
// enableRlsOnPayloadTables and the IF EXISTS guards of down().

export async function up({ db, payload, req }: MigrateUpArgs): Promise<void> {
  await db.execute(sql`
   CREATE TYPE "public"."enum_toolkit_files_language" AS ENUM('id', 'en');
  CREATE TYPE "public"."enum_toolkit_files_status" AS ENUM('pending', 'ready', 'failed', 'quarantined', 'archived');
  CREATE TABLE "lh_resources_rels" (
  	"id" serial PRIMARY KEY NOT NULL,
  	"order" integer,
  	"parent_id" integer NOT NULL,
  	"path" varchar NOT NULL,
  	"toolkit_files_id" integer
  );
  
  CREATE TABLE "_lh_resources_v_rels" (
  	"id" serial PRIMARY KEY NOT NULL,
  	"order" integer,
  	"parent_id" integer NOT NULL,
  	"path" varchar NOT NULL,
  	"toolkit_files_id" integer
  );
  
  CREATE TABLE "toolkit_files" (
  	"id" serial PRIMARY KEY NOT NULL,
  	"language" "enum_toolkit_files_language" NOT NULL,
  	"status" "enum_toolkit_files_status" DEFAULT 'ready' NOT NULL,
  	"prefix" varchar DEFAULT 'toolkits',
  	"_objectkey" varchar,
  	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
  	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
  	"url" varchar,
  	"thumbnail_u_r_l" varchar,
  	"filename" varchar,
  	"mime_type" varchar,
  	"filesize" numeric,
  	"width" numeric,
  	"height" numeric,
  	"focal_x" numeric,
  	"focal_y" numeric
  );
  
  CREATE TABLE "toolkit_files_locales" (
  	"label" varchar NOT NULL,
  	"id" serial PRIMARY KEY NOT NULL,
  	"_locale" "_locales" NOT NULL,
  	"_parent_id" integer NOT NULL
  );
  
  ALTER TABLE "payload_locked_documents_rels" ADD COLUMN "toolkit_files_id" integer;
  ALTER TABLE "lh_resources_rels" ADD CONSTRAINT "lh_resources_rels_parent_fk" FOREIGN KEY ("parent_id") REFERENCES "public"."lh_resources"("id") ON DELETE cascade ON UPDATE no action;
  ALTER TABLE "lh_resources_rels" ADD CONSTRAINT "lh_resources_rels_toolkit_files_fk" FOREIGN KEY ("toolkit_files_id") REFERENCES "public"."toolkit_files"("id") ON DELETE cascade ON UPDATE no action;
  ALTER TABLE "_lh_resources_v_rels" ADD CONSTRAINT "_lh_resources_v_rels_parent_fk" FOREIGN KEY ("parent_id") REFERENCES "public"."_lh_resources_v"("id") ON DELETE cascade ON UPDATE no action;
  ALTER TABLE "_lh_resources_v_rels" ADD CONSTRAINT "_lh_resources_v_rels_toolkit_files_fk" FOREIGN KEY ("toolkit_files_id") REFERENCES "public"."toolkit_files"("id") ON DELETE cascade ON UPDATE no action;
  ALTER TABLE "toolkit_files_locales" ADD CONSTRAINT "toolkit_files_locales_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."toolkit_files"("id") ON DELETE cascade ON UPDATE no action;
  CREATE INDEX "lh_resources_rels_order_idx" ON "lh_resources_rels" USING btree ("order");
  CREATE INDEX "lh_resources_rels_parent_idx" ON "lh_resources_rels" USING btree ("parent_id");
  CREATE INDEX "lh_resources_rels_path_idx" ON "lh_resources_rels" USING btree ("path");
  CREATE INDEX "lh_resources_rels_toolkit_files_id_idx" ON "lh_resources_rels" USING btree ("toolkit_files_id");
  CREATE INDEX "_lh_resources_v_rels_order_idx" ON "_lh_resources_v_rels" USING btree ("order");
  CREATE INDEX "_lh_resources_v_rels_parent_idx" ON "_lh_resources_v_rels" USING btree ("parent_id");
  CREATE INDEX "_lh_resources_v_rels_path_idx" ON "_lh_resources_v_rels" USING btree ("path");
  CREATE INDEX "_lh_resources_v_rels_toolkit_files_id_idx" ON "_lh_resources_v_rels" USING btree ("toolkit_files_id");
  CREATE INDEX "toolkit_files_updated_at_idx" ON "toolkit_files" USING btree ("updated_at");
  CREATE INDEX "toolkit_files_created_at_idx" ON "toolkit_files" USING btree ("created_at");
  CREATE UNIQUE INDEX "toolkit_files_filename_idx" ON "toolkit_files" USING btree ("filename");
  CREATE UNIQUE INDEX "toolkit_files_locales_locale_parent_id_unique" ON "toolkit_files_locales" USING btree ("_locale","_parent_id");
  CREATE INDEX "toolkit_files_locales_parent_id_idx" ON "toolkit_files_locales" USING btree ("_parent_id");
  ALTER TABLE "payload_locked_documents_rels" ADD CONSTRAINT "payload_locked_documents_rels_toolkit_files_fk" FOREIGN KEY ("toolkit_files_id") REFERENCES "public"."toolkit_files"("id") ON DELETE cascade ON UPDATE no action;
  CREATE INDEX "payload_locked_documents_rels_toolkit_files_id_idx" ON "payload_locked_documents_rels" USING btree ("toolkit_files_id");`)

  await enableRlsOnPayloadTables({ db, payload, req })
}

// Drops the toolkit files metadata and every resource's file list (the rows
// are lost; the objects in the bucket stay). The locked-documents column and
// its foreign key first, then the tables and the enums. IF EXISTS guards keep
// it order-independent, same pattern as 20261115_181459_m3_08_publication_files.
export async function down({ db }: MigrateDownArgs): Promise<void> {
  await db.execute(sql`
   ALTER TABLE IF EXISTS "payload_locked_documents_rels" DROP CONSTRAINT IF EXISTS "payload_locked_documents_rels_toolkit_files_fk";
  DROP INDEX IF EXISTS "payload_locked_documents_rels_toolkit_files_id_idx";
  ALTER TABLE IF EXISTS "payload_locked_documents_rels" DROP COLUMN IF EXISTS "toolkit_files_id";
  ALTER TABLE IF EXISTS "lh_resources_rels" DISABLE ROW LEVEL SECURITY;
  ALTER TABLE IF EXISTS "_lh_resources_v_rels" DISABLE ROW LEVEL SECURITY;
  ALTER TABLE IF EXISTS "toolkit_files" DISABLE ROW LEVEL SECURITY;
  ALTER TABLE IF EXISTS "toolkit_files_locales" DISABLE ROW LEVEL SECURITY;
  DROP TABLE IF EXISTS "lh_resources_rels" CASCADE;
  DROP TABLE IF EXISTS "_lh_resources_v_rels" CASCADE;
  DROP TABLE IF EXISTS "toolkit_files_locales" CASCADE;
  DROP TABLE IF EXISTS "toolkit_files" CASCADE;
  DROP TYPE IF EXISTS "public"."enum_toolkit_files_language";
  DROP TYPE IF EXISTS "public"."enum_toolkit_files_status";`)
}